// === Tab: mySketch.js ===
function setup() 
{
	createCanvas(1400, 500,WEBGL);
	background(255);
}

let counter=0
let zaxisCounter=0

function draw() 
{
	if(zaxisCounter<=900)
	{
		camera(0, zaxisCounter, 400+zaxisCounter, 0, 0, 0, 0, 1, 0)
		counter=counter+.01
		zaxisCounter=zaxisCounter+random(5)
		orbitControl()
		rotateY((3.14/2)+3.14)

		for(i=0;i<500;i++)
		{
			push()
			rotateX(random(3.14))
			translate(50,300-i,0)
			noFill()
			stroke(0)
			circle(0,0,100-i)
			stroke(255)
			circle(0,0,100-i*2)
			pop()
		}
	}
}

